            n.z = sqrt(max(0.0, 1.0 - dot(n.xy, n.xy)));
            float3 turned = float3(dot(decal.normal_rows[0].xyz, n.xzy),
                                   dot(decal.normal_rows[1].xyz, n.xzy),
                                   dot(decal.normal_rows[2].xyz, n.xzy));
